  "Hanbok_5": {"ko":"글로벌 의상","en":"World","ja":"世界の衣装","zh":"世界服饰","vi":"Trang phục toàn cầu","id":"Kostum Global","th":"เครื่องแต่งกายสากล","ru":"Глобальный костюм"},
