  "Hanbok_7": {"ko":"브랜드의상","en":"Brand","ja":"ブランド","zh":"品牌","vi":"Quần áo thương hiệu","id":"Pakaian bermerek","th":"เสื้อผ้าแบรนด์เนม","ru":"Фирменная одежда"},
